Action.Str:
var s = (local("evtprm2") || "") + " | " + (local("evtprm3") || "");
var tipo = "", valor = "", estab = "", parcelas = "1", m;

if (m = s.match(/Compra de R\$\s?([\d.]+,\d{2}) APROVADA em (.+?) para o cartão com final (\d{4})/)) {
  tipo = "despesa_credito"; valor = m[1]; estab = m[2];
} else if (m = s.match(/R\$\s?([\d.]+,\d{2}) em (\d+)x no crédito.*?APROVADO em (.+?)\.?$/)) {
  tipo = "despesa_nupay"; valor = m[1]; parcelas = m[2]; estab = m[3];
} else if (m = s.match(/cobrança paga de R\$\s?([\d.]+,\d{2})/)) {
  tipo = "receita_nupay"; valor = m[1];
}

valor = valor.replace(/\./g, "").replace(",", ".");

setLocal("tipo", tipo || "nenhum");
setLocal("valor", valor);
setLocal("estab", estab);
setLocal("parcelas", parcelas);

// Lança sozinho se o estabelecimento tem atalho (fin_atalho): a Edge Function responde lancado.
var agora = Math.floor(Date.now() / 1000);
setLocal("agora", String(agora));
setLocal("body", JSON.stringify({ tipo: local("tipo"), valor: local("valor"), estab: local("estab"),
  parcelas: local("parcelas"), ts: String(agora), auto: true }));

// Sem resposta, erro ou sem atalho: segue o fluxo de sempre (notificação pra tocar).
var r = {};
try { r = JSON.parse(local("http_data") || "{}"); } catch (e) {}
var ok = String(local("http_response_code") || "").charAt(0) === "2" && r.lancado === true;
setLocal("lancado", ok ? "sim" : "nao");
if (ok) setLocal("aviso", r.nome + " R$ " + local("valor").replace(".", ",") + " · " + String(r.categ || ""));

var agora = parseInt(local("agora"), 10) || Math.floor(Date.now() / 1000);
var d = new Date();
var p2 = function (n) { return ("0" + n).slice(-2); };
var hora = p2(d.getHours()) + ":" + p2(d.getMinutes()) + ":" + p2(d.getSeconds());
var base = local("estab") + " - R$ " + local("valor").replace(".", ",") + " (" + hora + ")";

var raw = global("FINPEND"), pend = {};
try { if (raw && raw.charAt(0) !== "%") pend = JSON.parse(raw); } catch (e) {}
for (var k in pend) { if (agora - pend[k].ts > 7 * 86400) delete pend[k]; }

var titulo = base, n = 2;
while (pend[titulo]) { titulo = base + " #" + n++; }

pend[titulo] = { tipo: local("tipo"), valor: local("valor"), estab: local("estab"),
                 parcelas: local("parcelas"), ts: agora };
setGlobal("FINPEND", JSON.stringify(pend));
setLocal("titulo", titulo);
